$filename='RH24-'.$type.'-'.$period.'.csv';header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$filename.'"');header('Cache-Control: no-store');echo "\xEF\xBB\xBF";
