function fde(float $v): string {return number_format($v,2,',','');}
function fperiod(string $date,string $p): bool {return substr($date,0,7)===$p;}
function fsale_payment_date(array $sale,array $transactions): string {$fallback=substr((string)($sale['updated_at']??$sale['created_at']??''),0,10);foreach($transactions as $tx){if(($tx['order_no']??'')===($sale['order_no']??'')&&($tx['status']??'')==='matched'&&(float)($tx['amount']??0)>0)return (string)$tx['booking_date'];}return $fallback;}
