if($type==='assets'){fc(['Anlagennr.','Bezeichnung','Kategorie','Anschaffungsdatum','Anschaffungswert','Nutzungsdauer Monate','Monats-AfA','kumulierte AfA','Restbuchwert','Sachkonto','Kostenstelle','Abgang']);foreach($data['assets'] as $r)fc([$r['asset_no'],$r['name'],$r['category'],$r['acquisition_date'],fde($r['purchase_price']),$r['useful_life_months'],fde($r['monthly_depreciation']),fde($r['accumulated_depreciation']),fde($r['book_value']),$r['account_code'],$r['cost_center_code']??'',$r['disposed_at']]);exit;}
if($type==='vat'){fc(['USt-Vorschau',$period]);fc(['Kennzahl','Beschreibung','Betrag']);$salesGross=$salesNet=$salesTax=$expGross=$expNet=$expTax=0.0;$vatMode=(string)($data['config']['vat_mode']??'Soll');foreach($data['sales'] as $r){if(($r['status']??'')==='cancelled')continue;$taxDate=$vatMode==='Ist'?fsale_payment_date($r,$data['transactions']):(string)$r['created_at'];if($vatMode==='Ist'&&($r['payment_status']??'')!=='paid')continue;if(!fperiod($taxDate,$period))continue;$salesGross+=$r['gross'];$salesNet+=$r['net'];$salesTax+=$r['tax'];}foreach($data['expenses'] as $r)if(fperiod($r['invoice_date'],$period)&&$r['record_status']==='active'){$expGross+=$r['gross_amount'];$expNet+=$r['net_amount'];$expTax+=$r['tax_amount'];}fc(['Umsatz netto','Aus erfassten Verkäufen',fde($salesNet)]);fc(['Umsatzsteuer','Aus erfassten Verkäufen',fde($salesTax)]);fc(['Vorsteuer','Aus erfassten Eingangsbelegen',fde($expTax)]);fc(['Zahllast-Vorschau','Umsatzsteuer minus Vorsteuer',fde($salesTax-$expTax)]);fc(['Hinweis','Arbeits-/Plausibilitätsauswertung; keine ERiC-Übermittlung','']);exit;}
if($type==='euer'){fc(['EÜR-Arbeitsauswertung',$period]);fc(['Art','Datum','Beleg','Geschäftspartner/Kategorie','Netto','Steuer','Brutto']);$income=0.0;$expense=0.0;foreach($data['sales'] as $r){if($r['payment_status']!=='paid')continue;$payDate=fsale_payment_date($r,$data['transactions']);if(!fperiod($payDate,$period))continue;$income+=$r['gross'];fc(['Einnahme',$payDate,$r['order_no'],$r['customer_name'],fde($r['net']),fde($r['tax']),fde($r['gross'])]);}foreach($data['expenses'] as $r){if($r['record_status']!=='active'||$r['payment_status']!=='paid'||empty($r['paid_at'])||!fperiod((string)$r['paid_at'],$period))continue;$expense+=$r['gross_amount'];fc(['Ausgabe',$r['paid_at'],$r['voucher_no'],$r['supplier_name']?:$r['category'],fde($r['net_amount']),fde($r['tax_amount']),fde($r['gross_amount'])]);}fc([]);fc(['Summe Einnahmen','','','','','',fde($income)]);fc(['Summe Ausgaben','','','','','',fde($expense)]);fc(['Überschuss','','','','','',fde($income-$expense)]);exit;}
if($type==='datev'){
