  $framework=$cfg['framework']==='SKR04'?'04':'03';$accountLen=max(4,min(8,(int)$cfg['datev_account_length']));$from=str_replace('-','',$period.'-01');$to=str_replace('-','',date('Y-m-t',strtotime($period.'-01')));$fy=substr($period,0,4).'0101';$ts=date('YmdHis').'000';$dik=preg_replace('/[^A-Z]/','',strtoupper((string)$cfg['datev_dictation_code']));$dik=substr($dik?:'BH',0,2);
  fc(['EXTF',700,21,'Buchungsstapel',13,$ts,'','RE','','',$berater,$mandant,$fy,$accountLen,$from,$to,'RH24 '.$period,$dik,1,0,0,'EUR','','','','',$framework,'','','','RH24-V91']);
