  foreach($data['sales'] as $r)if(fperiod($r['created_at'],$period)&&($r['status']??'')!=='cancelled')fc([fde(abs($r['gross'])),'S','','','','',$receivable,$revenue,'',date('dm',strtotime($r['created_at'])),$r['order_no'],'','','Ausgangsrechnung '.mb_substr($r['customer_name'],0,40)]);
  foreach($data['expenses'] as $r)if(fperiod($r['invoice_date'],$period)&&$r['record_status']==='active'){$konto=preg_replace('/\D/','',(string)$r['account_code']);if($konto==='')$konto=$cfg['framework']==='SKR04'?'6800':'4900';fc([fde(abs($r['gross_amount'])),'S','','','','',$konto,$payable,'',date('dm',strtotime($r['invoice_date'])),$r['voucher_no'],$r['invoice_no'],'','Eingangsrechnung '.mb_substr((string)($r['supplier_name']?:$r['category']),0,40)]);}
  exit;
}
